const timeZone = 'America/Los_Angeles';
const openDays = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'];
const opensAt = '09:00';
const closesAt = '17:00';

const now = new Date();
const clock = Object.fromEntries(
  new Intl.DateTimeFormat('en-GB', {
    timeZone,
    weekday: 'short',
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(now)
    .filter(({ type }) => ['weekday', 'hour', 'minute'].includes(type))
    .map(({ type, value }) => [type, value]),
);
const localTime = `${clock.hour}:${clock.minute}`;
const openNow = openDays.includes(clock.weekday)
  && localTime >= opensAt
  && localTime < closesAt;

return [{
  json: {
    openNow,
    localTime,
    timeZone,
    openDays,
    opensAt,
    closesAt,
    checkedAt: now.toISOString(),
  },
}];
